head.b:skin:
/* ===== RESET & BASE STYLES ===== */
* { box-sizing: border-box; margin: 0; padding: 0; }
body {
  font-family: 'Be Vietnam Pro', -apple-system, sans-serif;
  background-color: #1a120b;
  color: #e8dcc6;
  line-height: 1.6;
}
a { color: #e5b36a; text-decoration: none; transition: all 0.2s ease; }
a:hover { color: #f1c40f; }

/* ===== HEADER KHÔNG DÍNH (POSITION RELATIVE) ĐỂ KHÔNG CHÊ BÀN CỜ ===== */
.kybien-navbar {
  background: #8b0000;
  color: #ffffff;
  padding: 14px 20px;
  box-shadow: 0 4px 15px rgba(0, 0, 0, 0.4);
  position: relative;
  z-index: 10;
  margin-bottom: 10px;
}
.nav-container {
  max-width: 1200px;
  margin: 0 auto;
  display: flex;
  justify-content: space-between;
  align-items: center;
}
.brand-logo {
  font-size: 1.6rem;
  font-weight: 700;
  color: #fff;
  letter-spacing: 1px;
  display: flex;
  align-items: center;
  gap: 8px;
}
.brand-logo span { color: #f1c40f; }
.nav-links { display: flex; gap: 20px; list-style: none; align-items: center; }
.nav-links a { color: #ffffff; font-weight: 600; font-size: 0.95rem; }
.nav-links a:hover { color: #f1c40f; }

/* ===== MAIN LAYOUT TOÀN MÀN HÌNH ===== */
.main-wrapper {
  max-width: 1200px;
  margin: 10px auto 30px auto;
  padding: 0 15px;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.content-area {
  background: #271a10;
  padding: 20px;
  border-radius: 12px;
  border: 1px solid #5a3d22;
  box-shadow: 0 4px 20px rgba(0,0,0,0.4);
  width: 100%;
}
.post-title { font-size: 1.8rem; font-weight: 700; color: #f1c40f; margin-bottom: 15px; line-height: 1.3; }

/* Replay Viewer Component */
.kybien-viewer-container {
  background: #faf6f0;
  border: 2px solid #e2d7c5;
  border-radius: 10px;
  padding: 20px;
  margin: 20px 0;
  text-align: center;
}
.viewer-controls button {
  background: #8b0000;
  color: #fff;
  border: none;
  padding: 8px 16px;
  margin: 4px;
  border-radius: 6px;
  font-weight: 600;
  cursor: pointer;
}

.sa-truong-article {
  font-family: 'Merriweather', serif;
  background: #22160c;
  color: #e8dcc6;
  padding: 20px;
  border-left: 4px solid #8b0000;
  border-radius: 4px;
  margin-top: 25px;
}

.kybien-auth-buttons .btn-login {
  background: #f1c40f;
  color: #8b0000;
  padding: 8px 16px;
  border-radius: 20px;
  font-weight: 700;
  display: inline-block;
}
